import {R,part,previous,original,numberField as n,question as q} from './practice-shared.js';
export const inverseTasks=[
 {id:'i-powers',family:'local',level:1,title:'Variable Exponenten',source:'Originaltyp · B.5.2; Lecture Notes 2.17',sourceHref:'#/blaetter/5/B.5.2',purpose:'Variable Exponenten richtig ableiten und die Menge aller regulären Punkte bestimmen.',intro:R`Sei $f:(0,\infty)^2\to\mathbb R^2$, $f(x,y)=(x^y,y^x)$.`,
 parts:[part('Bestimme alle Punkte, an denen f ein lokaler Diffeomorphismus ist.',R`Auf dem offenen positiven Quadranten gilt $x^y=e^{y\ln x}$ und $y^x=e^{x\ln y}$. Daher ist $f$ glatt und $$Df=\begin{pmatrix}yx^{y-1}&x^y\ln x\\y^x\ln y&xy^{x-1}\end{pmatrix}.$$`,R`$$\det Df=x^y y^x(1-\ln x\ln y).$$ Der Vorfaktor ist positiv. Genau bei $\ln x\ln y\ne1$ ist $f$ ein lokaler $C^1$-Diffeomorphismus. Bei Determinante 0 wäre die Ableitung einer $C^1$-Inversen nach der Kettenregel unmöglich.`)],
 questions:[q(R`Was ist $\partial_y(x^y)$?`,R`$x^y\ln x$.`,R`Schreibe $x^y=e^{y\ln x}$ und leite nach dem Exponenten $y$ ab.`,R`$yx^{y-1}$.`,'Das ist die Ableitung nach x, nicht nach y.',R`$x^{y-1}$.`,'Bei einer variablen Hochzahl gilt die Exponentialregel mit ln x.')],
 hints:[R`Schreibe beide Potenzen mit $e$ und $\ln$.`,R`Zeile 1 enthält $yx^{y-1}$ und $x^y\ln x$.`,R`Klammere $x^y y^x>0$ aus der Determinante aus.`],fields:[n(R`$\det Df(1,1)$`,1)] },
 {...original('B.5.3'),id:'i-space',family:'local',level:2,title:'Drei Eingabevariablen',purpose:'Das lokale Kriterium auf eine konkrete 3×3-Jacobi-Matrix übertragen; die tatsächliche Formel lesen.',
 questions:[q('Welche Zeile entsteht aus der dritten Ausgabekomponente?',R`$(\cos\psi,0,-r\sin\psi)$.`,R`Die dritte Komponente lautet $r\cos\psi$. Sie hängt nicht von $\phi$ ab.`,R`$(\cos\phi,-r\sin\phi,0)$.`,'Das wäre die Ableitung einer anderen dritten Komponente r cos φ.',R`$(0,0,-\sin\psi)$.`,'Die Ableitung nach r und der Faktor r in der Ableitung nach ψ fehlen.')],
 hints:[R`Leite die tatsächlich angegebene Funktion ab: Die letzte Komponente ist $r\cos\psi$.`,R`Entwickle die Determinante nach der dritten Zeile; dort steht eine 0.`,R`Es ergibt sich $r^2\sin\phi\cos\phi\cos\psi$. Alle Faktoren müssen ungleich 0 sein.`] },
 {id:'i-polar',family:'image',level:0,title:'Polarkoordinaten auf einem Rechteck',source:'Originaltyp · B.4.3; Lecture Notes 2.17',sourceHref:'#/blaetter/4/B.4.3',purpose:'Radius, Winkel und mitgenommene Randstücke in die Bildmenge übertragen.',intro:R`Sei $f(r,\theta)=(r\cos\theta,r\sin\theta)$.`,
 parts:[part(R`Berechne $Df$ und seine Determinante. Bestimme dann das Bild von $S=[1,2]\times[0,\pi]$.`,
 R`Leite beide Ausgaben nach $r$ und $\theta$ ab: $$Df(r,\theta)=\begin{pmatrix}\cos\theta&-r\sin\theta\\\sin\theta&r\cos\theta\end{pmatrix}.$$ Die Determinante ist $r\cos^2\theta+r\sin^2\theta=r$.`,
 R`Das Rechteck $S$ beschreibt die erlaubten Eingaben $(r,\theta)$: $1\le r\le2$ und $0\le\theta\le\pi$. Die Ausgabe heißt $(u,v)=(r\cos\theta,r\sin\theta)$. Ihr Abstand vom Ursprung ist $$\sqrt{u^2+v^2}=\sqrt{r^2(\cos^2\theta+\sin^2\theta)}=r,$$ weil $r\ge1>0$. Die möglichen Bildradien liegen also genau zwischen 1 und 2.`,
 R`Schreibe dieselbe Radiusbedingung in $u,v$ auf: $$1\le r\le2\quad\Longleftrightarrow\quad1\le r^2\le4\quad\Longleftrightarrow\quad1\le u^2+v^2\le4.$$ Das ist keine neue Einschränkung: $u^2+v^2$ ist einfach das Quadrat des Radius.`,
 R`Der Winkel läuft von rechts ($0$) über oben bis nach links ($\pi$). Daher ist die Höhe $v=r\sin\theta\ge0$. Beide Winkelgrenzen und beide Radiusgrenzen sind erlaubt; die geraden Randstücke und die beiden Halbkreisbögen gehören dazu.`,
 R`Das Ergebnis ist der obere geschlossene Halbring: $$f(S)=\{(u,v)\in\mathbb R^2:1\le u^2+v^2\le4,\ v\ge0\}.$$ Beide Bedingungen gelten gleichzeitig: Abstand zwischen 1 und 2 und Lage auf oder über der horizontalen Achse.`,
 R`Umgekehrt wähle einen beliebigen Punkt dieser Menge. Sein Radius $r=\sqrt{u^2+v^2}$ liegt in $[1,2]$; wegen $v\ge0$ hat er einen Winkel $\theta\in[0,\pi]$. Damit ist $(r,\theta)\in S$ und $f(r,\theta)=(u,v)$. Also wird wirklich jeder Punkt des Halbrings erreicht.`)],
 questions:[q('Was wird aus der Bedingung 1 ≤ r ≤ 2?',R`$1\le u^2+v^2\le4$.`,R`Es gilt $u^2+v^2=r^2$.`,R`$1\le u^2+v^2\le2$.`,'Die Radiusgrenzen müssen quadriert werden.',R`$1<u^2+v^2<4$.`,'Die ursprünglichen Radiusgrenzen sind eingeschlossen.')],
 hints:[R`Nenne die Ausgabe $(u,v)$. Es gilt $u^2+v^2=r^2$; die Norm der Ausgabe ist hier genau der Eingaberadius $r$.`,R`Übersetze $1\le r\le2$ durch Quadrieren in $1\le u^2+v^2\le4$. Der Winkelbereich $[0,\pi]$ bedeutet obere Hälfte, also $v\ge0$.`,R`Alle Grenzen sind eingeschlossen. Begründe auch, dass jeder Punkt mit diesen beiden Bedingungen einen erlaubten Radius und Winkel hat.`],fields:[n(R`$\det Df(2,0)$`,2)] },
 {id:'i-square-image',family:'image',level:1,title:'Quadratische Abbildung einer Viertelscheibe',source:'Zahlenvariante · B.4.4 mit Radius 2',sourceHref:'#/blaetter/4/B.4.4',purpose:'Die Bildmenge durch Ausmultiplizieren, Norm und Vorzeichen bestimmen und ihre Vollständigkeit begründen.',intro:R`Sei $f(x,y)=(x^2-y^2,2xy)$ und $S=\{(x,y):x^2+y^2\le4,\ x,y\ge0\}$.`,
 recipeTitle:'Bildmenge ohne Winkelfunktionen',recipeSource:'Algebraischer Lösungsweg zu B.4.4.',
 recipe:[
 R`Ausgaben ablesen: $u$ ist die gesamte erste Komponente von $f$, $v$ die gesamte zweite. Hier: $u=x^2-y^2$, $v=2xy$.`,
 R`Radius prüfen: Setze die Ausdrücke in $u^2+v^2$ ein und multipliziere aus. Nutze danach die Bedingung $x^2+y^2\le4$. Hier hilft die Identität $u^2+v^2=(x^2+y^2)^2$.`,
 R`Vorzeichen prüfen: Lies an $v=2xy$ und den Eingabebedingungen ab, ob $v\ge0$ gilt. Prüfe auch, ob die Grenzen dazugehören.`,
 R`Alle Punkte erreichen: Begründe, dass für jeden erlaubten Bildradius der ganze obere Halbkreis entsteht. Erst damit ist die angegebene Menge wirklich das gesamte Bild.`],
 parts:[{...part(R`Berechne $Df$ und $\det Df$. Bestimme $f(S)$.`,
 R`**Jacobi-Matrix und Determinante:** $$Df(x,y)=\begin{pmatrix}2x&-2y\\2y&2x\end{pmatrix}.$$ Damit gilt $$\begin{aligned}\det Df&=2x\cdot2x-(-2y)\cdot2y\\&=4x^2+4y^2\\&=4(x^2+y^2).\end{aligned}$$`,
 R`**Ausgabekoordinaten ablesen:** Wir nennen die Ausgabe $(u,v)=f(x,y)$. Also $$u=x^2-y^2,\qquad v=2xy.$$ $u$ ist die gesamte erste Komponente, $v$ die gesamte zweite. Diese Ausdrücke stehen bereits in der Angabe.`,
 R`**In $u^2+v^2$ einsetzen und ausmultiplizieren:** $$\begin{aligned}u^2+v^2&=(x^2-y^2)^2+(2xy)^2\\&=x^4-2x^2y^2+y^4+4x^2y^2\\&=x^4+2x^2y^2+y^4\\&=(x^2+y^2)^2.\end{aligned}$$`,
 R`**Radius begrenzen:** Für die Eingaben in $S$ gilt $0\le x^2+y^2\le4$. Daher $$u^2+v^2=(x^2+y^2)^2\le4^2=16.$$ Die Ausgaben haben also Abstand höchstens $\sqrt{16}=4$ vom Ursprung.`,
 R`**Welche Hälfte? Vorzeichen prüfen:** In $S$ sind $x\ge0$ und $y\ge0$. Somit $$v=2xy\ge0.$$ Die Ausgabe liegt auf oder über der horizontalen Achse. Bisher wissen wir: Das Bild liegt in der oberen Halbkreisscheibe mit Radius 4.`,
 R`**Jeder Punkt wird erreicht:** Halte $s=x^2+y^2\in[0,4]$ fest. Dabei kann $x^2$ jeden Wert von $0$ bis $s$ annehmen; setze $y^2=s-x^2$ und wähle $x,y\ge0$. Dann durchläuft $$u=x^2-y^2=2x^2-s$$ alle Werte von $-s$ bis $s$. Wegen $u^2+v^2=s^2$ und $v\ge0$ entsteht der gesamte obere Halbkreis mit Radius $s$. Für $s=0$ entsteht der Ursprung. Alle $s\in[0,4]$ zusammen ergeben die ganze obere Halbkreisscheibe.`,
 R`**Bildmenge:** $$\boxed{\begin{gathered}f(S)=\{(u,v)\in\mathbb R^2:\\u^2+v^2\le16,\ v\ge0\}.\end{gathered}}$$ Die Fläche, der Halbkreisbogen, die horizontale Randstrecke und der Ursprung gehören dazu.`),sketch:'square-image-2'}],
 questions:[q('Welchen maximalen Radius hat die Bildmenge?','4.',R`Es gilt $u^2+v^2=(x^2+y^2)^2\le16$. Der Abstand vom Ursprung ist daher höchstens $\sqrt{16}=4$.`,'2.','2 ist der maximale Radius der Eingabemenge, nicht der Bildmenge.','16.','16 ist das Quadrat des maximalen Bildradius, nicht der Radius selbst.')],
 hints:[R`Lies $u=x^2-y^2$ und $v=2xy$ ab. Setze beide in $u^2+v^2$ ein.`,R`Multipliziere aus: $(x^2-y^2)^2+(2xy)^2=(x^2+y^2)^2$. Verwende dann $x^2+y^2\le4$.`,R`Aus $x,y\ge0$ folgt $v=2xy\ge0$. Für die Vollständigkeit: Halte $s=x^2+y^2$ fest und lasse $x^2$ von $0$ bis $s$ laufen.`] },
 {id:'i-exp',family:'image',level:2,title:'Lokale und globale Injektivität',source:'B.4.5 / Lecture Notes Beispiel 9; Zusatzfrage zum erweiterten Gebiet',sourceHref:'#/blaetter/4/B.4.5',purpose:'Lokale Umkehrbarkeit, globale Injektivität und vollständige Bildbeschreibung verbinden.',intro:R`Sei $f(x,y)=(e^x\cos y,e^x\sin y)$ und $A=\mathbb R\times(0,2\pi)$.`,
 parts:[part(R`Zeige lokale Umkehrbarkeit, Injektivität auf $A$ und bestimme $f(A)$.`,
 R`Für lokale Umkehrbarkeit: $A$ ist offen und $f$ glatt. Es gilt $$Df(x,y)=\begin{pmatrix}e^x\cos y&-e^x\sin y\\e^x\sin y&e^x\cos y\end{pmatrix},$$ $$\det Df=e^{2x}(\cos^2y+\sin^2y)=e^{2x}>0.$$ Der Umkehrsatz liefert in jedem Punkt von $A$ eine lokale $C^1$-Umkehrfunktion.`,
 R`Für Injektivität wähle zwei beliebige Punkte $(x,y),(s,t)\in A$ mit gleicher Ausgabe. Dann gelten beide Gleichungen $$e^x\cos y=e^s\cos t,\qquad e^x\sin y=e^s\sin t.$$ Quadriere die Gleichungen und addiere: $$e^{2x}(\cos^2y+\sin^2y)=e^{2s}(\cos^2t+\sin^2t)\quad\Longrightarrow\quad e^{2x}=e^{2s}\quad\Longrightarrow\quad x=s.$$`,
 R`Kürze nun den gemeinsamen positiven Faktor $e^x$ in beiden ursprünglichen Gleichungen. Es bleiben $\cos y=\cos t$ und $\sin y=\sin t$. Beide zusammen bedeuten, dass sich die Winkel um ein ganzzahliges Vielfaches von $2\pi$ unterscheiden. Wegen $y,t\in(0,2\pi)$ ist $-2\pi<y-t<2\pi$; das einzige mögliche Vielfache ist 0. Also $y=t$. Beide Koordinaten stimmen überein: $f$ ist auf $A$ injektiv.`,
 R`Für das Bild nenne die Ausgabe $(u,v)$. Ihr Radius ist ihre Norm: $$\rho=\sqrt{u^2+v^2}=\sqrt{e^{2x}(\cos^2y+\sin^2y)}=e^x.$$ Jetzt werden aus der Formel die möglichen Werte: Weil $x\in\mathbb R$ beliebig ist, erreicht $e^x$ jede positive Zahl. Für einen gewünschten Radius $\rho>0$ wähle $x=\ln\rho$. Der Radius wird nie 0; daher fehlt der Ursprung.`,
 R`Der Bildwinkel ist $y\in(0,2\pi)$. Er läuft einmal herum, aber die Richtung nach rechts auf der horizontalen Achse ($0$ bzw. $2\pi$) fehlt. Alle anderen Richtungen sind erlaubt. Zusammen mit dem fehlenden Ursprung ergibt das $$f(A)=\mathbb R^2\setminus\{(u,0):u\ge0\}.$$ Aus der ganzen Ebene wird die rechte Halbachse samt Ursprung entfernt: $(u,0)$ ist ein Punkt mit horizontaler Koordinate $u$ und Höhe 0; $u\ge0$ wählt die rechte Seite dieser Achse.`,
 R`Zur Vollständigkeit: Jeder Punkt dieser Menge hat einen Radius $\rho>0$ und einen Winkel $\theta\in(0,2\pi)$. Die Eingabe $(x,y)=(\ln\rho,\theta)$ liegt in $A$ und liefert genau diesen Punkt. Also wird jeder Punkt der angegebenen Bildmenge erreicht.`),
 part(R`Ist dieselbe Abbildung auf ganz $\mathbb R^2$ injektiv?`,R`Nein: $(0,0)\ne(0,2\pi)$, aber $$f(0,0)=(1,0)=f(0,2\pi).$$ Beide Eingaben liegen in $\mathbb R^2$. Die Determinante ist dennoch überall positiv: Lokale Umkehrbarkeit allein beweist keine globale Injektivität.`)],
 questions:[q('Was folgt allein aus det Df ≠ 0 auf dem ganzen Gebiet?','Lokale C¹-Umkehrbarkeit in jedem Punkt.','Der Umkehrsatz liefert lokale Aussagen. Globale Injektivität benötigt eine eigene Begründung.','Globale Injektivität.','Die periodische Winkelvariable liefert auf dem größeren Gebiet verschiedene Punkte mit gleichem Bild.','Dass jeder Punkt in R² erreicht wird.','Der Ursprung wird hier nie erreicht; die Determinante legt die globale Bildmenge nicht fest.')],
 hints:[R`Für Injektivität setze zwei Ausgaben gleich. Quadrieren und Addieren liefert $e^{2x}=e^{2s}$, also $x=s$.`,R`Kürze den gemeinsamen Faktor und vergleiche die Winkel im offenen Intervall $(0,2\pi)$. Für das Bild erreicht $e^x$ alle Radien $>0$; welche Richtung fehlt wegen der ausgeschlossenen Winkelgrenzen?`,R`Erkläre zum Ergebnis auch, wie du zu jedem erlaubten Radius und Winkel eine Eingabe findest. Für das größere Gebiet in (b) teste zwei Winkel mit Abstand $2\pi$.`] },
 {...previous('b-inverse'),id:'i-triangle',family:'inverseDerivative',level:0,title:'Direkt auflösbare Abbildung',purpose:'Globale Inverse durch Auflösen finden und die inverse Ableitung kontrollieren.',
 questions:[q(R`Welches Urbild gehört zum Bildpunkt $(3,1)$?`,R`$(2,1)$.`,R`Aus $y=1$ und $x+y^2=3$ folgt $x=2$.`,R`$(3,1)$.`,'Das Bild dieses Punktes wäre (4,1).',R`$(4,1)$.`,'Zum Auflösen muss y² von der ersten Bildkoordinate abgezogen werden.')],
 hints:[R`Die zweite Ausgabe liefert sofort $y=v$.`,R`Dann folgt $x=u-v^2$.`,R`Für die Matrixformel setze $(2,1)$ in $Df$ ein und invertiere.`],fields:[n(R`Eintrag $(1,2)$ von $D(f^{-1})(3,1)$`,-2)] },
 {...previous('a-inverse'),id:'i-double',family:'inverseDerivative',level:1,title:'Ableitung am Bildpunkt',purpose:'Das Verfahren bei verändertem innerem Winkel vollständig anwenden.',
 questions:[q(R`Wo wird $Df$ für $D(f^{-1})(0,2)$ ausgewertet?`,R`Bei $(\ln2,\pi/4)$.`,R`Das Bild hat Radius 2 und Winkel $\pi/2$. Wegen des Winkels $2y$ ist $y=\pi/4$.`,R`Bei $(0,2)$.`,'Das ist der Bildpunkt, nicht sein Urbild.',R`Bei $(\ln2,\pi/2)$.`,'Bei diesem y wäre der Bildwinkel π und das Bild (−2,0).')],
 hints:[R`Bestimme aus der Bildnorm zuerst $e^x=2$.`,R`Der Winkel des Bildes ist $\pi/2$; löse $2y=\pi/2$.`,R`Invertiere $Df(\ln2,\pi/4)=\begin{pmatrix}0&-4\\2&0\end{pmatrix}$.`],fields:[n(R`Eintrag $(1,2)$ der inversen Ableitung`,'1/2'),n(R`Eintrag $(2,1)$`,'-1/4')] },
 {id:'i-square-inverse',family:'inverseDerivative',level:2,title:'Quadratische Abbildung mit eingeschränktem Gebiet',source:'Eigene Kombination · B.4.4–B.4.5; Lecture Notes 2.17',sourceHref:'#/blaetter/4/B.4.4',purpose:'Eine zulässige Inversenverzweigung erkennen, das Urbild lösen und die Zahlenmatrix invertieren.',intro:R`Sei $f(x,y)=(x^2-y^2,2xy)$ auf $A=\{(x,y):x>0\}$.`,
 parts:[part(R`Begründe Injektivität auf $A$ und berechne $D(f^{-1})(3,4)$.`,R`Bezeichne das Bild mit $(u,v)$. Es gilt $u^2+v^2=(x^2+y^2)^2$, also $x^2+y^2=\sqrt{u^2+v^2}$. Zusammen mit $x^2-y^2=u$ folgt $x^2=(\sqrt{u^2+v^2}+u)/2$. Da $x>0$, ist $x$ eindeutig bestimmt; danach ist auch $y=v/(2x)$ eindeutig. Gleiche Bilder besitzen also gleiche Eingaben: $f$ ist injektiv.`,R`Aus $x^2-y^2=3$ und $2xy=4$ folgt $(x^2+y^2)^2=25$, also $x^2+y^2=5$. Damit $x^2=4$, wegen $x>0$ also $x=2$, und $y=1$.`,R`Das Gebiet ist offen, $f$ glatt und $\det Df=4(x^2+y^2)>0$ auf $A$. Daher existiert eine $C^1$-Inverse auf $f(A)$. Es gilt $$Df(2,1)=\begin{pmatrix}4&-2\\2&4\end{pmatrix},\quad D(f^{-1})(3,4)=\frac1{20}\begin{pmatrix}4&2\\-2&4\end{pmatrix}.$$`)],
 questions:[q('Welche Rolle spielt x > 0 bei der Urbildsuche?','Es wählt von den zwei entgegengesetzten Lösungen die zulässige aus.','Die Punkte (2,1) und (−2,−1) haben dasselbe Bild; nur einer liegt in A.','Es ändert die Formel für die Jacobi-Matrix.','Die Formel bleibt gleich; nur das Gebiet wird eingeschränkt.','Es erlaubt, den Urbildschritt zu überspringen.','Die Ableitung der Inversen muss weiterhin am passenden Urbild berechnet werden.')],
 hints:[R`Nutze $(x^2-y^2)^2+(2xy)^2=(x^2+y^2)^2$.`,R`Addiere $x^2-y^2=3$ und $x^2+y^2=5$.`,R`Mit $(x,y)=(2,1)$ ist die Determinante 20.`],fields:[n(R`Eintrag $(1,1)$ von $D(f^{-1})(3,4)$`,'1/5'),n(R`Eintrag $(2,1)$`,'-1/10')] }
];
